<script setup>definePageMeta({layout:false});const form=reactive({identity:'',password:''});const error=ref('');async function submit(){error.value='';try{await $fetch('/api/auth/login',{method:'POST',body:form});location.href='/'}catch(e){error.value=e.data?.statusMessage||'Login gagal'}}</script><template><main class="min-h-screen grid place-items-center p-6"><form class="panel w-full max-w-md space-y-4" @submit.prevent="submit"><div><h1 class="text-3xl font-black">PCI</h1><p>Panel Critical Info · Majalah dinding digital</p></div><input v-model="form.identity" class="input" placeholder="Email atau NIK" required><input v-model="form.password" type="password" class="input" placeholder="Password" required><p v-if="error" class="text-red-600">{{error}}</p><button class="btn-primary w-full">Sign in</button><div class="flex justify-between text-sm"><NuxtLink to="/signup" class="text-blue-700">Sign up</NuxtLink><NuxtLink to="/forgot" class="text-blue-700">Lupa password</NuxtLink></div><div class="text-xs bg-slate-100 p-3 rounded-xl">Demo admin: admin@pci.local / Admin123!<br>Demo user: 10001 / User123!</div></form></main></template>